export const monthlyStraightLine = (cost, salvage, lifeMonths) => (lifeMonths > 0 ? Math.round((cost - salvage) / lifeMonths) : 0);
/** Penyusutan bulan ini: tarif bulanan, dibatasi sisa nilai buku di atas residu. */
export const depreciationFor = (bookValue, salvage, monthly) => Math.max(0, Math.min(monthly, bookValue - salvage));
export function disposalLines(x) {
    const accum = x.cost - x.bookValue;
    const gain = x.proceeds - x.bookValue;
    const lines = [];
    if (accum)
        lines.push({ account: x.accumAccount, debit: accum, credit: 0, memo: 'Akumulasi penyusutan aset dilepas' });
    if (x.proceeds)
        lines.push({ account: x.bankAccount, debit: x.proceeds, credit: 0, bank: x.bank, memo: 'Hasil pelepasan' });
    if (gain < 0)
        lines.push({ account: x.lossAccount, debit: -gain, credit: 0, memo: 'Rugi pelepasan aset' });
    lines.push({ account: x.assetAccount, debit: 0, credit: x.cost, memo: 'Harga perolehan aset dilepas' });
    if (gain > 0)
        lines.push({ account: x.gainAccount, debit: 0, credit: gain, memo: 'Laba pelepasan aset' });
    return { lines, gain };
}
/** Periode YYYY-MM berikutnya. */
export function nextMonth(period) {
    const [y, m] = period.split('-').map(Number);
    return m === 12 ? `${y + 1}-01` : `${y}-${String(m + 1).padStart(2, '0')}`;
}
export const monthEndOf = (period) => {
    const [y, m] = period.split('-').map(Number);
    return new Date(Date.UTC(y, m, 0)).toISOString().slice(0, 10);
};
